const KEY='ChinaOil.monitoringInbox.v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function validatePacket(p){if(!p||p.schema_version!==1||p.source_app!=='ChinaOil Sense'||typeof p.id!=='string'||p.id.length>160||!p.id||typeof p.created_at!=='string'||!Number.isFinite(Date.parse(p.created_at))||!p.report||typeof p.report!=='object'||Array.isArray(p.report)||!['connectivity','stimulation','eor'].includes(p.domain))throw Error('不是有效的监测研判交接包v1');const advice=p.report.advice;if(advice!==undefined&&advice!==null){if(typeof advice!=='object'||Array.isArray(advice))throw Error('研判advice须为对象');for(const k of ['evidence','gaps'])if(advice[k]!==undefined&&(!Array.isArray(advice[k])||advice[k].some(x=>typeof x!=='string')))throw Error('研判'+k+'须为文本数组');if(advice.actions!==undefined&&(!Array.isArray(advice.actions)||advice.actions.some(x=>!x||typeof x!=='object'||Array.isArray(x)||['name','reason','requirements'].some(k=>x[k]!==undefined&&typeof x[k]!=='string'))))throw Error('措施候选须为结构化对象数组');}if(p.status!==undefined&&!['待专家审核','已阅，待专家审核'].includes(p.status))throw Error('监测包不能带入批准或执行状态');if(JSON.stringify(p).length>500000)throw Error('单份研判包上限500KB，请仅传递摘要');return p;}
export function readInbox(storage=globalThis.localStorage){try{const a=JSON.parse(storage.getItem(KEY)??'[]');if(!Array.isArray(a))return [];return a.filter(p=>{try{validatePacket(p);return true;}catch{return false;}}).slice(0,30);}catch{return [];}}
export function putInbox(packet,storage=globalThis.localStorage){validatePacket(packet);if(!storage)throw Error('浏览器存储不可用，请下载交接JSON并在决策平台导入');const all=[packet,...readInbox(storage).filter(p=>p.id!==packet.id)].slice(0,30);if(JSON.stringify(all).length>2000000)throw Error('本地收件箱超过2MB，请导出后整理');storage.setItem(KEY,JSON.stringify(all));return all;}
export function createPacket(domain,report){return validatePacket({schema_version:1,source_app:'ChinaOil Sense',id:globalThis.crypto?.randomUUID?.()??'monitoring-'+Date.now(),created_at:new Date().toISOString(),domain,status:'待专家审核',delivery:'同源同浏览器本地收件箱；非服务器或跨用户送达',report});}
export function renderInbox(){const packets=readInbox();return `<section class="panel"><div class="panel-head"><h2>监测研判收件箱</h2><span class="tag">${packets.length}份 · 当前浏览器</span></div><div class="panel-body"><div class="note">来自油藏生产态势感知智能体的研判摘要。采用同源浏览器本地存储；换设备、隐私模式或清除站点数据后不会同步。所有建议维持待专家审核，不自动执行措施。</div><label class="btn">导入监测研判JSON<input type="file" data-monitor-import accept=".json" style="max-width:230px"></label><a class="btn" href="../agent/#connectivity">返回监测智能体</a>${packets.length?packets.map(p=>`<article class="panel" style="margin-top:16px"><div class="panel-head"><h3>${esc(p.report.title??p.domain)}</h3><span class="tag">${esc(p.status)}</span></div><div class="panel-body"><p>${esc(p.created_at)} · ${esc(p.report.source)} · ${p.report.synthetic?'人工教学演示':'用户上传监测'}</p><p><b>可信度：</b>${esc(p.report.advice?.credibility??'未评价')}</p>${(p.report.advice?.evidence??[]).map(x=>`<p>• ${esc(x)}</p>`).join('')}${(p.report.advice?.actions??[]).map(a=>`<div class="note"><b>${esc(a.name)}</b><p>${esc(a.reason)}</p><p>实施前提：${esc(a.requirements)}</p></div>`).join('')}<p>核验缺口：${esc((p.report.advice?.gaps??[]).join('；'))}</p><details><summary>完整模型、区间和来源摘要</summary><pre style="white-space:pre-wrap;max-height:500px;overflow:auto">${esc(JSON.stringify(p.report,null,2))}</pre></details><button class="btn" data-monitor-read="${esc(p.id)}">标记已阅（仍需审核）</button></div></article>`).join(''):'<div class="empty">尚未收到监测研判。请在智能体中完成分析并点击“发送到决策平台”，或导入交接JSON。</div>'}</div></section>`;}
export function installInboxHandlers({render,notify}){document.addEventListener('click',e=>{const el=e.target.closest('[data-monitor-read]');if(!el)return;try{const p=readInbox().find(p=>p.id===el.dataset.monitorRead);if(p){putInbox({...p,status:'已阅，待专家审核'});render();notify('已记录阅读状态，未批准或执行措施');}}catch(e){notify(e.message);}});document.addEventListener('change',async e=>{if(!e.target.matches('[data-monitor-import]'))return;try{const f=e.target.files[0];if(!f)return;if(f.size>500000)throw Error('交接JSON上限500KB');const p=validatePacket(JSON.parse(await f.text()));putInbox(p);render();notify('已导入本地监测收件箱');}catch(e){notify(e.message);}});window.addEventListener('storage',e=>{if(e.key===KEY&&location.hash==='#monitoring-inbox')render();});}
